const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([35.114837, 11.184384]);
  const region = point.buffer(1000); // 1km buffer

  // Date ranges (±3 days for each target date)
  const date2019 = ee.Date('2019-02-06');
  const date2022 = ee.Date('2022-02-14');
  const dateRange = 3; // days

  // 2. Data Acquisition - Sentinel-1 for reliable water detection
  const s1_2019 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(region)
    .filterDate(date2019.advance(-dateRange, 'day'), date2019.advance(dateRange, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .sort('system:time_start');

  const s1_2022 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(region)
    .filterDate(date2022.advance(-dateRange, 'day'), date2022.advance(dateRange, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .sort('system:time_start');

  // Check collection sizes
  const count2019 = s1_2019.size().getInfo();
  const count2022 = s1_2022.size().getInfo();

  console.log(`2019 Images: ${count2019}, 2022 Images: ${count2022}`);

  if (count2019 === 0 || count2022 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get closest images
  const img2019 = ee.Image(s1_2019.first());
  const img2022 = ee.Image(s1_2022.first());

  // Water detection using VV threshold (water typically < -15 dB)
  const waterThreshold = -15;

  const water2019 = img2019.select('VV').lt(waterThreshold);
  const water2022 = img2022.select('VV').lt(waterThreshold);

  // Calculate water pixel counts
  const waterCount2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 20,
    maxPixels: 1e9
  }).get('VV').getInfo();

  const waterCount2022 = water2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 20,
    maxPixels: 1e9
  }).get('VV').getInfo();

  console.log(`2019 Water Pixels: ${waterCount2019}`);
  console.log(`2022 Water Pixels: ${waterCount2022}`);

  // Check for no valid pixels
  if (waterCount2019 === 0 || waterCount2022 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid results
  if (waterCount2019 === null || waterCount2022 === null || 
      isNaN(waterCount2019) || isNaN(waterCount2022)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water extent
  const waterGreater2022 = waterCount2022 > waterCount2019;

  console.log(`Water extent greater in 2022: ${waterGreater2022}`);

  // Final answer
  if (waterGreater2022) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
